<template><view class="page"><view class="player"><video v-if="url" class="video" :src="url" autoplay controls object-fit="contain" @play="playing=true" @error="failed"/><view v-else class="placeholder">{{loading?'正在启动回放…':'回放启动失败'}}</view></view><view class="panel"><text class="title">{{name||channelId}}</text><text class="meta">{{startTime}} 至 {{endTime}}</text><view class="controls"><button @click="toggle">{{playing?'暂停':'继续'}}</button><picker :range="speeds" @change="changeSpeed"><view class="speed">{{currentSpeed}} 倍速⌄</view></picker></view><button class="stop" @click="stopAndBack">停止回放</button></view></view></template>
<script setup lang="ts">
import{ref}from'vue';import{onHide,onLoad,onUnload}from'@dcloudio/uni-app';import{chooseH5Stream}from'@/api/play';import{startPlayback,stopPlayback,pausePlayback,resumePlayback,speedPlayback}from'@/api/record';import{showRequestError}from'@/utils/request';const deviceId=ref(''),channelId=ref(''),name=ref(''),startTime=ref(''),endTime=ref(''),streamId=ref(''),url=ref(''),loading=ref(true),playing=ref(false),currentSpeed=ref(1),speeds=[0.5,1,2,4];let stopped=false;async function start(){try{const stream=await startPlayback(deviceId.value,channelId.value,startTime.value,endTime.value);streamId.value=stream.stream||'';url.value=chooseH5Stream(stream);if(!url.value)throw new Error('没有可用的 H5 回放地址')}catch(e){showRequestError(e)}finally{loading.value=false}}async function toggle(){if(!streamId.value)return;try{if(playing.value){await pausePlayback(streamId.value);playing.value=false}else{await resumePlayback(streamId.value);playing.value=true}}catch(e){showRequestError(e)}}async function changeSpeed(e:any){const value=speeds[Number(e.detail.value)];try{await speedPlayback(streamId.value,value);currentSpeed.value=value}catch(err){showRequestError(err)}}async function stop(){if(stopped||!streamId.value)return;stopped=true;try{await stopPlayback(deviceId.value,channelId.value,streamId.value)}catch{}}async function stopAndBack(){await stop();uni.navigateBack()}function failed(){url.value='';playing.value=false;uni.showToast({title:'当前浏览器无法播放该回放流',icon:'none'})}onLoad(q=>{deviceId.value=String(q?.deviceId||'');channelId.value=String(q?.channelId||'');name.value=String(q?.name||'');startTime.value=String(q?.startTime||'');endTime.value=String(q?.endTime||'');start()});onHide(stop);onUnload(stop)
</script><style scoped>.page{min-height:100vh;background:#10131a}.player{width:100%;aspect-ratio:16/9;background:#050608}.video,.placeholder{width:100%;height:100%}.placeholder{display:flex;align-items:center;justify-content:center;color:#8992a6}.panel{margin-top:20rpx;padding:34rpx;color:#fff;background:#191e29}.title,.meta{display:block}.title{font-size:34rpx;font-weight:600}.meta{margin-top:14rpx;color:#9da7bb;font-size:23rpx}.controls{display:flex;align-items:center;gap:18rpx;margin-top:34rpx}.controls button,.speed{padding:18rpx 34rpx;color:#eaf0ff;background:#2a3242;border-radius:16rpx;font-size:25rpx}.controls button{margin:0}.stop{margin-top:36rpx;color:#fff;background:#d94b4b;border-radius:18rpx}</style>
